                transition: height var(--mega-height-speed) var(--mega-ease), left var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease), right var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease), border-bottom-left-radius var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease), border-bottom-right-radius var(--navbar-scroll-duration, 0s) var(--navbar-scroll-ease);
                background-color: var(--color-scheme-1--dark-second, #0e121a);
