            }

            .navbar-v2_dropdown.is-open .nav_dropdown-chevron {
                transform: rotate(180deg);
            }

            /* 4. Fluid column gap */
            @media (min-width: 992px) {
                .navbar-v2_dropdown-content-left {
                    --gap-min: 24px;
                    --gap-max: 48px;
                    --gap-delta: 24;
                    column-gap: clamp( var(--gap-min), calc(var(--gap-min) + (100vw - 992px) * var(--gap-delta) / 208), var(--gap-max) ) !important;
                }
            }

            /* 5. data-hide-narrow */
            @media (min-width: 992px) and (max-width: 1130px) {
