                                            <div class="solutions-tab_tab-content-left">
                                                <h3 class="heading-style-h5 text-weight-semibold">Women &#x27;s health </h3>
                                                <div class="spacer-small"></div>
                                                <p class="text-size-regular opacity-80">
                                                    Example use cases:<br/>
                                                    ‍<br/>
                                                    1. Monitor cardiovascular changes across menstrual cycles, pregnancy, and menopause.<br/>
                                                    2. Track maternal heart health for safer pregnancies.<br/>3. Identify and address unique cardiovascular risks in women.
                                                </p>
                                            </div>
                                            <div class="solutions-tab_tab-graphic-wrapper">
                                                <img loading="lazy" src="https://cdn.prod.website-files.com/680280c18df8e68403545b30/680280c18df8e68403545ddb_Women%27s%20health.svg" alt="" class="solutions-tab_tab-graphic"/>
